        void update_dsource_species_dtemperature_reaction_167(Species& dsource_species_dtemperature_,
                                                           const Species& species,
                                                           const double& temperature,
                                                           const double& log_temperature,
                                                           const double& mixture_concentration,
                                                           const double& pressure_,
                                                           const double& equilibrium_constant_167,
                                                           const double& dequilibrium_constant_167_dtemperature,
                                                           const double& dlog_temperature_dtemperature)
{
                double forward_reaction_167 = call_forward_reaction_167(temperature, log_temperature);
        double dforward_reaction_167_dtemperature = dcall_forward_reaction_167_dtemperature(temperature,log_temperature);

        dforward_reaction_167_dtemperature += dcall_forward_reaction_167_dlog_temperature(temperature,log_temperature) * dlog_temperature_dtemperature;


        

        // Reaction 167: C2H4 + CH3 <=> C2H3 + CH4

        double drate_of_progress_167_dtemperature =
        multiply(species[19] * species[10], dforward_reaction_167_dtemperature)
        -
        multiply(species[18] * species[11],
                 divide_chain(forward_reaction_167,
                              dforward_reaction_167_dtemperature,
                              equilibrium_constant_167,
                              dequilibrium_constant_167_dtemperature));

        dsource_species_dtemperature_[19] += -drate_of_progress_167_dtemperature;
        dsource_species_dtemperature_[10] += -drate_of_progress_167_dtemperature;
        dsource_species_dtemperature_[18] += drate_of_progress_167_dtemperature;
        dsource_species_dtemperature_[11] += drate_of_progress_167_dtemperature;
}

