        double rate_of_progress_7 = multiply(species[1] * species[2], forward_reaction_7) - multiply(species[4], divide(forward_reaction_7, equilibrium_constant_7));
        


        drate_of_progress_dspecies = multiply(species[2], forward_reaction_7);//7 1
        jacobian_net_production_rates[2][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[3][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[5][2] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[1], forward_reaction_7);//7 2
