double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_12 = multiply(species[1] * species[6], forward_reaction_12) - multiply(pow_gen2(species[4]), divide(forward_reaction_12, equilibrium_constant_12));
        

        //drate_of_progress_dspecies[12] = {double(0)};
