void update_jacobian_reaction_38(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_38,
                                               const double& dequilibrium_constant_38_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_38 =  call_forward_reaction_38(species, temperature, log_temperature, mixture_concentration);
        double dforward_reaction_38_dtemperature = dcall_forward_reaction_38_dtemperature(species,temperature,log_temperature,mixture_concentration);

        Species dforward_reaction_38_dspecies = dcall_forward_reaction_38_dspecies(species,temperature,log_temperature,mixture_concentration);

        dforward_reaction_38_dtemperature += dcall_forward_reaction_38_dlog_temperature(species,temperature,log_temperature,mixture_concentration) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_38 = multiply(species[7] * species[12], forward_reaction_38) - multiply(species[20], divide(forward_reaction_38, equilibrium_constant_38));
        


        drate_of_progress_dspecies = multiply(species[12], forward_reaction_38);//38 7
        jacobian_net_production_rates[8][8] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[13][8] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[21][8] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[7], forward_reaction_38);//38 12
        jacobian_net_production_rates[8][13] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[13][13] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[21][13] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -divide(forward_reaction_38, equilibrium_constant_38); //38 20
        jacobian_net_production_rates[8][21] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[13][21] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[21][21] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[7] * species[12] - divide(species[20], equilibrium_constant_38),
                  dforward_reaction_38_dspecies);
        jacobian_net_production_rates[8] = add_species_to_chemical_state(jacobian_net_production_rates[8], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[13] = add_species_to_chemical_state(jacobian_net_production_rates[13], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[21] = add_species_to_chemical_state(jacobian_net_production_rates[21], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


