void update_jacobian_reaction_60(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const double& dpressure_dtemperature_,
                                               const Species& dpressure_dspecies_,

                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_60,
                                               const double& dequilibrium_constant_60_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_60 =  call_forward_reaction_60(temperature, pressure_);
        double dforward_reaction_60_dtemperature = dcall_forward_reaction_60_dtemperature(temperature,pressure_);

        dforward_reaction_60_dtemperature += dcall_forward_reaction_60_dpressure(temperature,pressure_) * dpressure_dtemperature_;
        Species   dforward_reaction_60_dspecies = scale_gen(dcall_forward_reaction_60_dpressure(temperature,pressure_), dpressure_dspecies_);


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_60 = multiply(species[9] * species[5], forward_reaction_60) - multiply(species[15] * species[0], divide(forward_reaction_60, equilibrium_constant_60));
        


        drate_of_progress_dspecies = multiply(species[9], forward_reaction_60);//60 5
        jacobian_net_production_rates[10][6] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[6][6] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][6] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][6] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[5], forward_reaction_60);//60 9
        jacobian_net_production_rates[10][10] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[6][10] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][10] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][10] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[15], divide(forward_reaction_60, equilibrium_constant_60));// 60 0
        jacobian_net_production_rates[10][1] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[6][1] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][1] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][1] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[0], divide(forward_reaction_60, equilibrium_constant_60));// 60 15
        jacobian_net_production_rates[10][16] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[6][16] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][16] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][16] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[9] * species[5] - divide(species[15] * species[0], equilibrium_constant_60),
                  dforward_reaction_60_dspecies);
        jacobian_net_production_rates[10] = add_species_to_chemical_state(jacobian_net_production_rates[10], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[6] = add_species_to_chemical_state(jacobian_net_production_rates[6], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[16] = add_species_to_chemical_state(jacobian_net_production_rates[16], scale_gen(1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[1] = add_species_to_chemical_state(jacobian_net_production_rates[1], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


