void update_jacobian_reaction_75(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_75,
                                               const double& dequilibrium_constant_75_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_75 =  call_forward_reaction_75(species, temperature, log_temperature, mixture_concentration);
        double dforward_reaction_75_dtemperature = dcall_forward_reaction_75_dtemperature(species,temperature,log_temperature,mixture_concentration);

        Species dforward_reaction_75_dspecies = dcall_forward_reaction_75_dspecies(species,temperature,log_temperature,mixture_concentration);

        dforward_reaction_75_dtemperature += dcall_forward_reaction_75_dlog_temperature(species,temperature,log_temperature,mixture_concentration) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_75 = multiply(species[10] * species[1], forward_reaction_75) - multiply(species[11], divide(forward_reaction_75, equilibrium_constant_75));
        


        drate_of_progress_dspecies = multiply(species[10], forward_reaction_75);//75 1
        jacobian_net_production_rates[11][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[12][2] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[1], forward_reaction_75);//75 10
        jacobian_net_production_rates[11][11] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][11] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[12][11] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -divide(forward_reaction_75, equilibrium_constant_75); //75 11
        jacobian_net_production_rates[11][12] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][12] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[12][12] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[10] * species[1] - divide(species[11], equilibrium_constant_75),
                  dforward_reaction_75_dspecies);
        jacobian_net_production_rates[11] = add_species_to_chemical_state(jacobian_net_production_rates[11], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[2] = add_species_to_chemical_state(jacobian_net_production_rates[2], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[12] = add_species_to_chemical_state(jacobian_net_production_rates[12], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


