void update_jacobian_reaction_80(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const double& dpressure_dtemperature_,
                                               const Species& dpressure_dspecies_,

                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_80,
                                               const double& dequilibrium_constant_80_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_80 =  call_forward_reaction_80(temperature, pressure_);
        double dforward_reaction_80_dtemperature = dcall_forward_reaction_80_dtemperature(temperature,pressure_);

        dforward_reaction_80_dtemperature += dcall_forward_reaction_80_dpressure(temperature,pressure_) * dpressure_dtemperature_;
        Species   dforward_reaction_80_dspecies = scale_gen(dcall_forward_reaction_80_dpressure(temperature,pressure_), dpressure_dspecies_);


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_80 = multiply(species[10] * species[4], forward_reaction_80) - multiply(species[15] * species[0], divide(forward_reaction_80, equilibrium_constant_80));
        


        drate_of_progress_dspecies = multiply(species[10], forward_reaction_80);//80 4
        jacobian_net_production_rates[11][5] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[5][5] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][5] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][5] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[4], forward_reaction_80);//80 10
        jacobian_net_production_rates[11][11] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[5][11] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][11] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][11] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[15], divide(forward_reaction_80, equilibrium_constant_80));// 80 0
        jacobian_net_production_rates[11][1] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[5][1] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][1] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][1] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[0], divide(forward_reaction_80, equilibrium_constant_80));// 80 15
        jacobian_net_production_rates[11][16] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[5][16] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][16] += drate_of_progress_dspecies;
        jacobian_net_production_rates[1][16] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[10] * species[4] - divide(species[15] * species[0], equilibrium_constant_80),
                  dforward_reaction_80_dspecies);
        jacobian_net_production_rates[11] = add_species_to_chemical_state(jacobian_net_production_rates[11], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[5] = add_species_to_chemical_state(jacobian_net_production_rates[5], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[16] = add_species_to_chemical_state(jacobian_net_production_rates[16], scale_gen(1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[1] = add_species_to_chemical_state(jacobian_net_production_rates[1], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


