void update_jacobian_reaction_90(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_90,
                                               const double& dequilibrium_constant_90_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_90 =  call_forward_reaction_90(species, temperature, log_temperature, mixture_concentration);
        double dforward_reaction_90_dtemperature = dcall_forward_reaction_90_dtemperature(species,temperature,log_temperature,mixture_concentration);

        Species dforward_reaction_90_dspecies = dcall_forward_reaction_90_dspecies(species,temperature,log_temperature,mixture_concentration);

        dforward_reaction_90_dtemperature += dcall_forward_reaction_90_dlog_temperature(species,temperature,log_temperature,mixture_concentration) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_90 = multiply(species[16], forward_reaction_90) - multiply(species[15] * species[1], divide(forward_reaction_90, equilibrium_constant_90));
        


        drate_of_progress_dspecies = forward_reaction_90;// 90 16 
        jacobian_net_production_rates[17][17] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][17] += drate_of_progress_dspecies;
        jacobian_net_production_rates[2][17] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[15], divide(forward_reaction_90, equilibrium_constant_90));// 90 1
        jacobian_net_production_rates[17][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][2] += drate_of_progress_dspecies;
        jacobian_net_production_rates[2][2] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -multiply(species[1], divide(forward_reaction_90, equilibrium_constant_90));// 90 15
        jacobian_net_production_rates[17][16] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[16][16] += drate_of_progress_dspecies;
        jacobian_net_production_rates[2][16] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[16] - divide(species[15] * species[1], equilibrium_constant_90),
                  dforward_reaction_90_dspecies);
        jacobian_net_production_rates[17] = add_species_to_chemical_state(jacobian_net_production_rates[17], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[16] = add_species_to_chemical_state(jacobian_net_production_rates[16], scale_gen(1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[2] = add_species_to_chemical_state(jacobian_net_production_rates[2], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


