void update_jacobian_reaction_114(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_114,
                                               const double& dequilibrium_constant_114_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_114 =  call_forward_reaction_114(species, temperature, log_temperature, mixture_concentration);
        double dforward_reaction_114_dtemperature = dcall_forward_reaction_114_dtemperature(species,temperature,log_temperature,mixture_concentration);

        Species dforward_reaction_114_dspecies = dcall_forward_reaction_114_dspecies(species,temperature,log_temperature,mixture_concentration);

        dforward_reaction_114_dtemperature += dcall_forward_reaction_114_dlog_temperature(species,temperature,log_temperature,mixture_concentration) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_114 = multiply(species[17] * species[1], forward_reaction_114) - multiply(species[18], divide(forward_reaction_114, equilibrium_constant_114));
        


        drate_of_progress_dspecies = multiply(species[17], forward_reaction_114);//114 1
        jacobian_net_production_rates[18][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[19][2] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[1], forward_reaction_114);//114 17
        jacobian_net_production_rates[18][18] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][18] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[19][18] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -divide(forward_reaction_114, equilibrium_constant_114); //114 18
        jacobian_net_production_rates[18][19] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][19] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[19][19] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[17] * species[1] - divide(species[18], equilibrium_constant_114),
                  dforward_reaction_114_dspecies);
        jacobian_net_production_rates[18] = add_species_to_chemical_state(jacobian_net_production_rates[18], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[2] = add_species_to_chemical_state(jacobian_net_production_rates[2], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[19] = add_species_to_chemical_state(jacobian_net_production_rates[19], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


