void update_jacobian_reaction_132(SpeciesJacobian& jacobian_net_production_rates,
                                               const Species& species,
                                               const double& temperature,
                                               const double& log_temperature,
                                               const double& mixture_concentration,
                                               const double& pressure_,
                                               const Species& dtemperature_dspecies_,
                                               const double& equilibrium_constant_132,
                                               const double& dequilibrium_constant_132_dtemperature,
                                               const double& dlog_temperature_dtemperature)
{
                double forward_reaction_132 =  call_forward_reaction_132(species, temperature, log_temperature, mixture_concentration);
        double dforward_reaction_132_dtemperature = dcall_forward_reaction_132_dtemperature(species,temperature,log_temperature,mixture_concentration);

        Species dforward_reaction_132_dspecies = dcall_forward_reaction_132_dspecies(species,temperature,log_temperature,mixture_concentration);

        dforward_reaction_132_dtemperature += dcall_forward_reaction_132_dlog_temperature(species,temperature,log_temperature,mixture_concentration) * dlog_temperature_dtemperature;


double drate_of_progress_dspecies  = double(0);
        double rate_of_progress_132 = multiply(species[18] * species[1], forward_reaction_132) - multiply(species[19], divide(forward_reaction_132, equilibrium_constant_132));
        


        drate_of_progress_dspecies = multiply(species[18], forward_reaction_132);//132 1
        jacobian_net_production_rates[19][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][2] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[20][2] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = multiply(species[1], forward_reaction_132);//132 18
        jacobian_net_production_rates[19][19] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][19] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[20][19] += drate_of_progress_dspecies;
        drate_of_progress_dspecies = -divide(forward_reaction_132, equilibrium_constant_132); //132 19
        jacobian_net_production_rates[19][20] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[2][20] += -drate_of_progress_dspecies;
        jacobian_net_production_rates[20][20] += drate_of_progress_dspecies;


        Species drate_of_progress_dspecies_all_species =
        scale_gen(species[18] * species[1] - divide(species[19], equilibrium_constant_132),
                  dforward_reaction_132_dspecies);
        jacobian_net_production_rates[19] = add_species_to_chemical_state(jacobian_net_production_rates[19], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[2] = add_species_to_chemical_state(jacobian_net_production_rates[2], scale_gen(-1.0, drate_of_progress_dspecies_all_species));
        jacobian_net_production_rates[20] = add_species_to_chemical_state(jacobian_net_production_rates[20], scale_gen(1.0, drate_of_progress_dspecies_all_species));

                        }


